import{_ as e,o as d,c as l,a3 as a}from"./chunks/framework.CDCjIvJ8.js";const y=JSON.parse('{"title":"API endpoints","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":1789296458000}'),s={name:"reference/api.md"};function i(o,t,n,r,c,h){return d(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="api-endpoints" tabindex="-1">API endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API endpoints&quot;">​</a></h1><p>60 endpoints under <code>/api/v1</code>. The interactive schema is at <code>/docs</code> in non-production environments.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><p><strong>Authentication</strong> — <code>Authorization: Bearer &lt;jwt&gt;</code> on everything except the public endpoints marked below.</p><p><strong>Errors</strong> — uniform envelope:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;permission_denied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;request_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a1b2c3…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Branch on <code>code</code>; the prose is free to change. Quote <code>request_id</code> when reporting a problem — it is in the response header too.</p><p><strong>404 for unauthorized resources</strong> — accessing something you do not own returns 404, not 403. A 403 would confirm it exists.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/</code></td><td style="text-align:left;">Public</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/health</code></td><td style="text-align:left;">Public — shallow liveness</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/health</code></td><td style="text-align:left;"><strong>Authenticated</strong> — dependency status</td></tr></tbody></table><p><code>/api/v1/health</code> probes four services per call, so it is authenticated: open access is both an amplification vector and a readout of which dependencies are down.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/auth/register</code></td><td style="text-align:left;">Public</td><td style="text-align:left;">Always creates a <strong>STUDENT</strong>. No <code>role</code> field.</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/auth/register-faculty</code></td><td style="text-align:left;">Public</td><td style="text-align:left;">Requires a valid registration code</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/auth/login</code></td><td style="text-align:left;">Public</td><td style="text-align:left;">Rate limited 5/min, 30/hr</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/auth/refresh</code></td><td style="text-align:left;">Public</td><td style="text-align:left;">Rotates the refresh token</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/auth/logout</code></td><td style="text-align:left;">Public</td><td style="text-align:left;">Revokes server-side; always 204</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/auth/me</code></td><td style="text-align:left;">Authenticated</td><td style="text-align:left;"><strong>Authoritative</strong> role and status</td></tr></tbody></table><h2 id="invitations" tabindex="-1">Invitations <a class="header-anchor" href="#invitations" aria-label="Permalink to &quot;Invitations&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/invitations/preview?token=</code></td><td style="text-align:left;">Public</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/invitations/accept</code></td><td style="text-align:left;">Public</td></tr></tbody></table><p>The only unauthenticated write endpoints, rate limited under the auth scope. The email comes from the invitation record, never the request body.</p><h2 id="classes-roster" tabindex="-1">Classes &amp; roster <a class="header-anchor" href="#classes-roster" aria-label="Permalink to &quot;Classes &amp; roster&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/classes</code></td><td style="text-align:left;">Teacher</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/classes</code></td><td style="text-align:left;">Teacher — own classes</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/classes/enrolled</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>GET</code> <code>PATCH</code></td><td style="text-align:left;"><code>/classes/{id}</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/classes/{id}/rotate-join-code</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/classes/{id}/roster</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/classes/{id}/invitations</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/classes/{id}/invitations</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/classes/{id}/invitations/resend</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>DELETE</code></td><td style="text-align:left;"><code>/classes/{id}/invitations/{iid}</code></td><td style="text-align:left;">Teacher — owner</td></tr><tr><td style="text-align:left;"><code>DELETE</code></td><td style="text-align:left;"><code>/classes/{id}/roster/{eid}</code></td><td style="text-align:left;">Teacher — owner</td></tr></tbody></table><p>Bulk invite returns <strong>202</strong>: the roster updates synchronously, delivery happens out of band.</p><h2 id="drafts" tabindex="-1">Drafts <a class="header-anchor" href="#drafts" aria-label="Permalink to &quot;Drafts&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/drafts</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/drafts/upload</code></td><td style="text-align:left;">Student — 40/hr, 15 MB</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/drafts</code></td><td style="text-align:left;">Student — own</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/drafts/{id}</code></td><td style="text-align:left;">Student — owner</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/drafts/{id}/versions</code></td><td style="text-align:left;">Student — owner</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/drafts/{id}/compare?v1=&amp;v2=</code></td><td style="text-align:left;">Student — owner</td></tr></tbody></table><h2 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/evaluations</code></td><td style="text-align:left;">Student — owner of the draft</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/evaluations/{id}</code></td><td style="text-align:left;">Owner, their instructor, or admin</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/loopholes/{id}</code></td><td style="text-align:left;">Owner, their instructor, or admin</td></tr></tbody></table><h2 id="ai-rate-limited-token-budgeted" tabindex="-1">AI (rate limited, token budgeted) <a class="header-anchor" href="#ai-rate-limited-token-budgeted" aria-label="Permalink to &quot;AI (rate limited, token budgeted)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/ai/explain-evaluation</code></td><td style="text-align:left;">Authenticated</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/ai/assist-drafting</code></td><td style="text-align:left;">Authenticated</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/rag/retrieve</code></td><td style="text-align:left;">Authenticated</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/chat/send</code></td><td style="text-align:left;">Authenticated</td></tr><tr><td style="text-align:left;"><code>POST</code> <code>GET</code></td><td style="text-align:left;"><code>/conversations</code></td><td style="text-align:left;">Student — own</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/conversations/{id}/messages</code></td><td style="text-align:left;">Student — owner</td></tr></tbody></table><h2 id="learning" tabindex="-1">Learning <a class="header-anchor" href="#learning" aria-label="Permalink to &quot;Learning&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/skills/my-skills</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>GET</code> <code>POST</code></td><td style="text-align:left;"><code>/roadmap</code>, <code>/roadmap/generate</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>PATCH</code></td><td style="text-align:left;"><code>/roadmap/items/{id}/complete</code></td><td style="text-align:left;">Student — owner</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/quizzes</code>, <code>/quizzes/{id}</code></td><td style="text-align:left;">Authenticated</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/quizzes/submit</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/exercises</code>, <code>/exercises/{id}</code>, <code>/exercises/my-attempts</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/exercises/attempt</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/progress</code></td><td style="text-align:left;">Student</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/leaderboard</code></td><td style="text-align:left;"><strong>Class-scoped</strong></td></tr></tbody></table><p>Quiz and exercise responses never include <code>correct_option</code> or <code>model_solution</code> — withheld by column-level grants.</p><h2 id="coursework" tabindex="-1">Coursework <a class="header-anchor" href="#coursework" aria-label="Permalink to &quot;Coursework&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/assignments</code></td><td style="text-align:left;">Teacher</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/assignments</code>, <code>/assignments/{id}</code></td><td style="text-align:left;">Student — their classes</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/teachers/assignments</code></td><td style="text-align:left;">Teacher — own</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/submissions</code></td><td style="text-align:left;">Student — owner of the draft</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/submissions/assignment/{id}</code></td><td style="text-align:left;">Teacher — owner of the assignment</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/submissions/{id}/override</code></td><td style="text-align:left;">Teacher — owner; <strong>audited</strong></td></tr></tbody></table><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/documents/reference/upload</code></td><td style="text-align:left;">Teacher — audited</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/documents/reference</code></td><td style="text-align:left;">Authenticated</td></tr><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/documents/classify</code></td><td style="text-align:left;"><strong>Authenticated</strong> (was public)</td></tr></tbody></table><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Path</th><th style="text-align:left;">Access</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/analytics/cohort?class_id=</code></td><td style="text-align:left;">Teacher — own classes only</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/teachers/cohort-analytics</code></td><td style="text-align:left;">Teacher — own classes only</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Both were global</p><p>These aggregated every profile, evaluation and skill record in the database, so an instructor&#39;s &quot;cohort&quot; dashboard described the entire platform. Now scoped through class membership.</p></div><h2 id="rate-limits" tabindex="-1">Rate limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Scope</th><th style="text-align:left;">Limit</th><th style="text-align:left;">Applies to</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AUTH</code></td><td style="text-align:left;">5/min, 30/hr</td><td style="text-align:left;">Login, register, refresh, invitations</td></tr><tr><td style="text-align:left;"><code>LLM</code></td><td style="text-align:left;">10/min, 300/day</td><td style="text-align:left;">Chat, AI assist, RAG, roadmap generation</td></tr><tr><td style="text-align:left;"><code>UPLOAD</code></td><td style="text-align:left;">40/hr</td><td style="text-align:left;">Draft and reference uploads</td></tr><tr><td style="text-align:left;"><code>INVITE</code></td><td style="text-align:left;">200/hr</td><td style="text-align:left;">Bulk invite and resend</td></tr><tr><td style="text-align:left;"><code>DEFAULT</code></td><td style="text-align:left;">120/min</td><td style="text-align:left;">Everything else</td></tr></tbody></table><p>Responses carry <code>X-RateLimit-Limit</code> and <code>X-RateLimit-Remaining</code>; a 429 carries <code>Retry-After</code>.</p><p>LLM endpoints additionally charge a <strong>daily token budget</strong> (<code>LLM_TOKEN_BUDGET_PER_DAY</code>), because request counts cannot bound spend.</p>',39)])])}const f=e(s,[["render",i]]);export{y as __pageData,f as default};
